216	func errorColumn(title string, get func(netiface.Interface) *uint64) datatable.Column[netiface.Interface] {
217		return datatable.Column[netiface.Interface]{
218			Title: title, Sizing: datatable.SizingFixed, Optional: true, MinWidth: 8,
219			Cell: func(i netiface.Interface) string {
220				n := get(i)
221				if n == nil {
222					return "-"
223				}
224				return strconv.FormatUint(*n, 10)
225			},
226			Style: func(i netiface.Interface) lipgloss.Style {
227				n := get(i)
228				if n == nil || *n == 0 {
229					return theme.DimStyle
230				}
231				return theme.StatusWarningStyle
232			},
233			Less: func(a, b netiface.Interface) bool {
234				return errorCount(get(a)) < errorCount(get(b))
235			},
